    var ts = t + n.t, d = Math.max(0.012, n.d), a = n.a === undefined ? 1 : n.a, at = Math.min(o.att || 0.008, d * 0.3), rl = Math.min(o.rel || 0.015, d * 0.4), f = n.f, k;
